parameters.jsCode:
// **컨테이너의 TZ에 기대지 않는다.** n8n 2.x는 Code 노드를 별도 러너 프로세스에서
// 돌리는데 그 프로세스는 TZ를 물려받지 않아 UTC로 동작한다 — 실측으로 확인했다
// (TZ=Asia/Seoul인데도 new Date()가 GMT+0000을 냈다). 시간표는 한국 시각 기준이므로
// UTC에 9시간을 더한 값으로 판정하고, 시각을 읽고 쓸 때는 UTC 계열 함수를 쓴다.
const KST_OFFSET_MINUTES = 9 * 60;
const now = new Date(Date.now() + KST_OFFSET_MINUTES * 60 * 1000);
const today = now.toISOString().slice(0, 10);
// 시간표를 읽지 못하면 기본 시간표로 넘어가지 않는다. 그 상태로 진행하면 실제와
// 다른 시간표로 출결을 기록하게 된다. 오류로 표시해 Slack 알림 후 중단시킨다.
let scheduleText = '';
let scheduleError = '';
try {
  // $binary는 Code 노드에서 정의되지 않는다(항목별 실행 모드 전용). 앞 노드의
  // 항목을 직접 집어야 한다. 실측으로 $binary가 undefined인 것을 확인했다.
  const incoming = $input.first().binary;
  if (incoming && incoming.data && incoming.data.data) {
    scheduleText = Buffer.from(incoming.data.data, 'base64').toString('utf8');
  } else {
    scheduleError = '시간표 문서를 읽지 못했습니다. 경로를 확인하세요.';
  }
} catch (error) {
  scheduleError = '시간표 문서를 여는 중 오류가 났습니다: ' + String(error).slice(0, 200);
}
const defaultPeriods = [
  { name: 'morning-study', start: '08:00', end: '08:40' },
  { name: 'period-1', start: '08:40', end: '10:10' },
  { name: 'period-2', start: '10:20', end: '11:50' },
  { name: 'period-3', start: '13:00', end: '14:30' },
  { name: 'period-4', start: '14:40', end: '16:10' },
  { name: 'period-5', start: '16:20', end: '17:50' },
  { name: 'night-period-1', start: '19:00', end: '20:30' },
  { name: 'night-period-2', start: '20:40', end: '22:00' }
];
const parsed = [];
// 구간 이름은 그 줄에서 끝난다. [^|]는 줄바꿈까지 삼켜서 표가 아닌 형식일 때
// 다음 줄을 이름에 붙이고 구간을 통째로 건너뛴다. 개행을 제외해 막는다.
const lineRegex = /\*\*(\d{2}:\d{2})\s*~\s*(\d{2}:\d{2})\*\*\s*\|\s*([^|\n\r]+)/g;
let match;
let index = 0;
while ((match = lineRegex.exec(scheduleText)) !== null) {
  const label = match[3].trim();
  if (!/(자습|교시|study|period)/i.test(label)) continue;
  parsed.push({ name: label || `period-${++index}`, start: match[1], end: match[2] });
}
if (!scheduleError && !parsed.length) {
  scheduleError = '시간표 문서에서 공부 시간 구간을 찾지 못했습니다. 형식을 확인하세요.';
}
const periods = parsed.length ? parsed : defaultPeriods;
function at(time) {
  const [hour, minute] = time.split(':').map(Number);
  const value = new Date(now);
  value.setUTCHours(hour, minute, 0, 0);
  return value;
}
const active = periods.find((period) => now >= at(period.start) && now <= at(period.end));

// **교시 종료 보고는 시간 창이 아니라 원장으로 판정한다.**
// 예전에는 "끝난 지 5분 안"에 든 교시만 보고했다. 트리거 주기가 5분과 같아서 n8n
// 재시작 등으로 틱이 한 번만 밀려도 그 교시 보고서가 조용히 사라졌다. 지금은 "끝났는데
// 아직 보고하지 않은 교시"를 찾고, 실제로 Slack 전송이 끝난 뒤에야 원장에 적는다
// (Mark Period Reported). 그래서 틱이 밀리거나 전송이 실패해도 다음 틱이 이어받는다.
const CATCH_UP_MINUTES = Number($env.PERIOD_REPORT_CATCH_UP_MINUTES || 60);
let ended = null;
let missedPeriods = [];
// 시간표를 읽지 못했으면 원장에 손대지 않는다. 이때 periods는 기본 시간표라,
// 여기서 기록하면 실제와 다른 교시 이름이 원장에 남는다.
if (!scheduleError) {
  const staticData = $getWorkflowStaticData('global');
  staticData.reportedPeriods = staticData.reportedPeriods || {};
  staticData.watchingSince = staticData.watchingSince || {};
  // 오늘 것만 남긴다. 날짜별로 쌓이면 워크플로 정적 데이터가 끝없이 자란다.
  for (const key of Object.keys(staticData.reportedPeriods)) {
    if (!key.startsWith(today + '|')) delete staticData.reportedPeriods[key];
  }
  for (const key of Object.keys(staticData.watchingSince)) {
    if (key !== today) delete staticData.watchingSince[key];
  }
  // 오늘 처음 (정상적으로) 돈 시각. 이보다 먼저 끝난 교시는 애초에 관측하지 않았으니
  // 보고 대상이 아니다. 이 기준이 없으면 낮에 워크플로를 처음 켤 때 오전 교시를 전부
  // "놓쳤다"고 알리게 된다.
  if (!staticData.watchingSince[today]) staticData.watchingSince[today] = now.toISOString();
  const watchingSince = new Date(staticData.watchingSince[today]).getTime();

  const pending = periods
    .map((period) => ({ period, endAt: at(period.end).getTime() }))
    .filter((entry) => now.getTime() >= entry.endAt)
    .filter((entry) => entry.endAt >= watchingSince)
    .filter((entry) => !staticData.reportedPeriods[today + '|' + entry.period.name])
    .sort((a, b) => a.endAt - b.endAt);
  // 따라잡기 창을 넘긴 교시는 포기한다. 여기까지 밀렸다면 다음 교시가 이미 한참
  // 지났고, 늦은 보고서를 올리면 어느 교시 것인지 오히려 헷갈린다. 대신 포기했다는
  // 사실을 Slack으로 알린다 — 조용히 사라지게 두지 않는다.
  const missed = pending.filter((entry) => now.getTime() - entry.endAt > CATCH_UP_MINUTES * 60 * 1000);
  for (const entry of missed) staticData.reportedPeriods[today + '|' + entry.period.name] = 'missed';
  missedPeriods = missed.map((entry) => entry.period.name);
  const next = pending.find((entry) => now.getTime() - entry.endAt <= CATCH_UP_MINUTES * 60 * 1000);
  ended = next ? next.period : null;
}
return [{ json: { today, periods, scheduleError, activePeriod: active || null, endedPeriod: ended, missedPeriods, classroomId: $env.CLASSROOM_ID, classroomName: $env.CLASSROOM_NAME || $env.CLASSROOM_ID } }];

// 좌석 상태는 바로 앞 HTTP 응답에서, 시간표·강의실 정보는 Parse Schedule에서 가져온다.
// HTTP 응답이 $json을 통째로 덮어써서 Parse Schedule이 만든 today·classroomId가
// 여기까지 따라오지 않는다.
//
// **n8n 표현식은 노드를 이름으로만 부를 수 있다.** 편집기에서 'Parse Schedule'의 이름을
// 바꾸면 이 참조가 깨지는데, 그냥 두면 undefined가 아래로 흘러 빈 보고서가 조용히
// 만들어진다. 그래서 여기서 즉시 멈춘다. 이름이 실제 노드와 맞는지는
// scripts/validate_workflow_artifacts.py도 검사한다. 워크플로에 남은 노드 이름 참조는
// 이 한 곳뿐이다 — 나머지는 실행기가 되돌려 주는 context로 넘긴다.
const states = $input.first().json.states || [];
let input;
try {
  input = $('Parse Schedule').first().json;
} catch (error) {
  throw new Error("'Parse Schedule' 노드를 찾지 못했습니다. 노드 이름을 바꿨다면 이 코드의 참조도 함께 바꾸세요: " + String(error).slice(0, 200));
}
if (!input || !input.today || !input.classroomId) {
  throw new Error("'Parse Schedule'이 today·classroomId를 주지 않았습니다. 노드 이름이나 출력이 바뀌었는지 확인하세요.");
}
const workflowData = $getWorkflowStaticData('global');
workflowData.lastState = workflowData.lastState || {};
// 이벤트는 날짜별로 쌓이는데 실제로 쓰는 것은 오늘 것뿐이다. 지난 날짜를 버리지 않으면
// 워크플로 정적 데이터가 끝없이 자라 저장이 느려진다.
workflowData.events = (workflowData.events || []).filter((event) => event.key && event.key.startsWith(input.today + '|'));
const now = new Date().toISOString();
const period = input.activePeriod || input.endedPeriod || { name: 'manual-run' };
const meaningfulStates = new Set(['ABSENT', 'WRONG_SEAT', 'IN_CLASSROOM', 'UNKNOWN', 'PRESENT']);
const newEvents = [];
for (const state of states) {
  const studentId = state.student_id;
  const current = state.current_state || 'UNKNOWN';
  if (!studentId || !meaningfulStates.has(current)) continue;
  const last = workflowData.lastState[studentId];
  const changed = !last || last.state !== current;
  workflowData.lastState[studentId] = { state: current, at: now };
  if (!changed) continue;
  const seatNumber = state.assigned_seat_label || state.current_seat_label || state.assigned_seat_id || state.current_seat_id || '';
  const key = [input.today, input.classroomId, period.name, studentId, current, state.last_observed_at || now].join('|');
  if (workflowData.events.some((event) => event.key === key)) continue;
  const event = {
    key,
    period: period.name,
    observed_at: state.last_observed_at || now,
    seat_number: seatNumber,
    student_id: studentId,
    student_name: state.student_name,
    student_state: current
  };
  workflowData.events.push(event);
  newEvents.push(event);
}
const allEvents = workflowData.events.filter((event) => event.key.startsWith(input.today + '|' + input.classroomId + '|'));
const eventsBase64 = Buffer.from(JSON.stringify(allEvents), 'utf8').toString('base64');
const workbookPath = `RPAs/study-status-report/reports/study_status_${input.today}_${input.classroomId}.xlsx`;
const endedPeriodName = (input.endedPeriod && input.endedPeriod.name) || '';
// **Slack에 보이는 문구는 한국어로 쓴다.** 이 채널을 보는 사람은 강의실 관리자다.
// 교시 이름은 시간표 문서에서 그대로 온다('1교시', '아침 자습'처럼 받침 유무가 갈린다).
// 조사를 붙이면 '아침 자습가 끝났습니다'가 되므로 '[이름 종료]' 형태로 조사를 피한다.
// periodName은 원장 키라서 손대지 않는다 — 바뀌는 것은 사람이 읽는 문구뿐이다.
// **뒤 노드들이 쓸 값은 context에 담아 실행기에 함께 보낸다.** 실행기가 이걸 그대로
// 돌려주므로 HTTP 응답 뒤의 노드들이 이 노드를 이름으로 거슬러 참조할 필요가 없다. 이름을 바꿔도 깨지지 않고, 어느 교시를 보고했는지가 응답에 실려
// 와서 Mark Period Reported가 원장에 적을 수 있다.
const context = {
  today: input.today,
  classroomId: input.classroomId,
  classroomName: input.classroomName,
  periodName: endedPeriodName || period.name,
  endedPeriodName,
  shouldSendPeriodReport: Boolean(input.endedPeriod),
  uploadTitle: endedPeriodName
    ? `자습 현황 (${endedPeriodName}) - ${input.classroomName} ${input.today}`
    : `자습 현황 - ${input.classroomName} ${input.today}`,
  // endedPeriodName이 비면 shouldSendPeriodReport도 false라 이 문구는 Slack까지 가지
  // 않는다. 그래도 실행 이력에는 남으므로 사실대로 적는다 — '수동 실행'이라고 적었더니
  // 수업 중 정기 틱까지 수동 실행으로 보였다.
  uploadComment: endedPeriodName
    ? `[${endedPeriodName} 종료] 오늘 자습 현황을 정리한 관리 문서입니다.`
    : `[보고 대상 아님] 교시 종료 시점이 아니라 전송하지 않습니다.`
};
return [{ json: { ...input, newEvents, allEvents, eventsBase64, workbookPath, context } }];

// Parse Schedule과 같은 이유로 KST 기준 날짜를 쓴다. UTC로 두면 자정 직후
// 일일 리포트가 전날 날짜로 만들어진다.
const today = new Date(Date.now() + 9 * 60 * 60 * 1000).toISOString().slice(0, 10);
const workflowData = $getWorkflowStaticData('global');
const classroomId = $env.CLASSROOM_ID;
const classroomName = $env.CLASSROOM_NAME || classroomId;
const allEvents = (workflowData.events || []).filter((event) => event.key && event.key.startsWith(today + '|' + classroomId + '|'));
const eventsBase64 = Buffer.from(JSON.stringify(allEvents), 'utf8').toString('base64');
const workbookPath = `RPAs/study-status-report/reports/study_status_${today}_${classroomId}.xlsx`;
// 교시 보고와 같은 이유로 context를 실행기에 실어 보낸다 — 뒤 노드가 이 노드를
// 이름으로 참조하지 않게 하려는 것이다.
const context = {
  today,
  classroomId,
  classroomName,
  periodName: 'daily-report',
  uploadTitle: `일일 자습 리포트 - ${classroomName} ${today}`,
  // 시트 이름은 create_management_workbook.py가 만드는 실제 이름이다.
  uploadComment: "[오늘 자습 종료] '일일 리포트' 시트에 상태별 종합과 학생별 자리 이탈 정도가 정리돼 있습니다."
};
return [{ json: { today, classroomId, classroomName, allEvents, eventsBase64, workbookPath, context } }];

// **Slack 전송이 끝난 뒤에야 보고 완료로 적는다.** 여기 도달하기 전에 실패하면
// 원장에 남지 않으므로 다음 5분 틱이 같은 교시를 다시 보고한다. 전송이 실패했다고
// 보고서가 조용히 사라지지 않게 하려는 것이다. 어느 교시였는지는 실행기가 되돌려 준
// context에서 읽는다 — 노드 이름으로 거슬러 올라가지 않는다.
const context = ($input.first().json || {}).context;
if (!context || !context.today || !context.periodName) {
  throw new Error('실행기 응답에 context가 없습니다. Create Workbook과 Upload Workbook to Slack이 context를 함께 보내는지 확인하세요.');
}
const staticData = $getWorkflowStaticData('global');
staticData.reportedPeriods = staticData.reportedPeriods || {};
const key = context.today + '|' + context.periodName;
staticData.reportedPeriods[key] = new Date().toISOString();
return [{ json: { reportedPeriod: key } }];
